    data: "",
    paragrafos: [
      "Frei Bruno Linden é muito famoso em Santa Catarina. Foi um Frade Franciscano, Padre e Missionário alemão, que pertencia a mesma Ordem do Frei Rui – a Ordem Franciscana Menor. Há mais de 30 anos é realizada a Romaria do Frei Bruno em Joaçaba, que atrai milhares de devotos. É considerado Servo de Deus e em 2013 foi iniciado seu processo de beatificação. Nesta linda e verídica história, o médico Dr. Orlando Depiné, irmão do Frei Rui, nos conta um pouco sobre o encontro dos dois grandes Frades Franciscanos: Frei Bruno e Frei Rui.",
      "Obrigada por compartilhar essa linda história, Orlando.",
      "Paz e Bem!",
      "Frei Rui e Frei Bruno: o encontro de dois Santos",
      "Depois que o Frei Rui partiu para a Casa de Deus, sempre tive vontade de narrar estes fatos, reais, que me foram contados pela minha mãe há uns quarenta e oito anos, quando eu era seminarista franciscano em Agudos.",
      "Narrou-me isso, talvez, porque ela desejava muito dois sacerdotes na família. Mas sempre respeitando nosso livre arbítrio.",
      "Em 1945, após o fim da segunda guerra mundial, a cidade de Rodeio (SC), a terra natal de Frei Rui Guido Depiné era habitada basicamente por muitas famílias com numerosos filhos, de descendência italiana. Exceção se fazia em relação aos padres franciscanos da Paróquia São Francisco de Assis, onde ainda hoje se encontra o noviciado.",
      "Esses Padres, na sua maioria, vieram da Alemanha. Um deles marcou profundamente a cidade e o povo de Rodeio, município vasto em território pois contemplava também as comunidades de Dr. Pedrinho, Alto Forcação, Capivari, Santa Maria, Benedito Novo, Alto Benedito, entre outras. As estradas eram quase inexistentes.",
      "Frei Bruno Linden (nascido em 08/09/1876 e falecido em 25/02/1960), andava muitos quilômetros no lombo duma mula.",
      "Homem alto, justo, corajoso, meio rústico. Dócil. Mãos marcadas pelo trabalho. Sempre com o hábito de São Francisco. Portava uma valise preta com óleos santos, água benta, a Hóstia Sagrada, alguma vestimenta de padre. Na cabeça, tinha uma espécie de boina preta. Sempre, numa das mãos, um guarda-chuva.",
      "Como minha mãe, Dona Lídia, (e mãe do Frei Rui) era de origem alemã e ela dominava bem a língua germânica, Frei Bruno, com certa frequência vinha “se aconselhar” com ela, em alemão. Queria saber das famílias, de possíveis vocações…queria saber dos rumores da cidade após a guerra. Tudo em alemão para que não houvesse vazamento dessas informações. Ele, com isso, visitava famílias em conflito. Talvez, pessoas estressadas e atingidas pela Alemanha, na grande guerra.",
      "Certo dia, Frei Bruno Linden visitou minha mãe, com suas surradas vestes Franciscanas, guarda-chuva, boina, maletinha! Ele, de modo geral, não adentrava a residência, a não ser que Dona Lídia lhe pedisse para abençoar algum filho doente ou para abençoar a casa contra trovões, raios, ventanias, incêndios, cobras…",
      "O Rui, 3-4 aninhos, descalço, foi ao encontro do Padre.",
      "- Este lhe pergunta: “Bambino come ti chami?” (Menino como você se chama?).",
      "- “Mi chiamo Rui Guido Depiné”, respondeu-lhe prontamente.",
      "Frei Bruno perguntou: “Cosa vuoi essere quando cresci?” (o que você quer ser quando crescer?).",
      "Rui Depiné: - “Voglio essere come Padre Bruno”. (Quero ser como Padre Bruno).",
      "O padre deu um pingo de atenção! (lembra alguém?), e colocou os apetrechos no chão, impôs suas ásperas mãos na cabeça daquele menino e o abençoou!",
      "Frei Bruno disse: “Sarai un grande sacerdote” (serás um grande sacerdote). “Mamma questo ragazzo sará un grande prete” (Mama, esse menino será um grande padre).",
      "O pequeno menino, encara os dois nos olhos, sorri mas tem lágrimas na face. Corre pelo terreiro, quase a voar! O Espírito Santo borbulhava nele. Alguns anos depois, entra no Seminário de Rodeio, Rio Negro, Agudos, noviciado em Rodeio, Filosofia em Curitiba, Teologia em Petrópolis. Ordenação em Rodeio na data de 18/07/1971.",
      "Foi isso que minha mãe me contou certa manhã enquanto me fazia companhia, à espera do ônibus que me levaria a Agudos.",
      "Frei Bruno Linden",
      "A mãe do Frei Rui: Dona Lídia Maria Benkendorf Depiné",
      "Flores para Dona Lídia: muito obrigado por tudo!",
      "Dr. Orlando Depiné. Hoje é médico.",
      "A profecia do Frei Bruno se cumpriu. Frei Rui foi um grande Sacerdote.",
      "Frei Rui: ordenado em 18/07/1971. Paz e Bem!",
    ],
