      "Setembro, mês da Bíblia. Com a profundidade que lhe é característica e a simplicidade que desenvolveu para falar com o povo, o Frei Rui nos brinda com uma reflexão sobre nosso Livro Sagrado: a Bíblia.",
      "Frei Rui era um estudioso. E a Bíblia foi seu maior estudo. Vamos ler a Bíblia. Vamos seguir os mandamentos que estão escritos na Bíblia.",
      "Vamos, também, agradecer pelo empenho do Frei Rui que durante todo seu sacerdócio nos orientou, como orienta agora, com esta bela homilia.",
      "Muito obrigado, Frei Rui. Sua bênção!",
      "A Bíblia",
      "Frei Rui Guido Depiné o.f.m.",
      "Este domingo abre o mês da Bíblia.",
      "A Bíblia como o livro mais lido e mais vendido no mundo inteiro.",
      "Não é um livro de ciência, não é um livro de história, não é um livro de matemática que ensina a contar e calcular. Mas é um livro diferente. Nele está a palavra de Deus ou falada por Jesus Cristo ou falada pelos homens que Deus fez falar como, por exemplo, os Profetas e os Apóstolos.",
