      "O “Milagre” da Multiplicação dos Sorvetes",
      "A cidade de Piraquara, onde o Frei Rui viveu por quase 40 anos, é um local de temperatura fria. Mas no verão, pode fazer muito calor. Em uma destas tardes bem quentes de Piraquara, o Frei Rui foi visitar uma família a quem ele dava assistência. Esta família tinha quatro crianças. A rua empoeirada, a casa modesta, as dificuldades do local; pareciam deixar a tarde mais quente, sem brisa, sem expectativa de amenizar o calor. Então o Frei Rui teve uma ideia: comprar sorvete para aquelas crianças. Foi uma alegria tão grande que parecia inacreditável! Quando o Frei Rui foi até Kombi branca buscar o dinheiro, para que as crianças pudessem comprar o sorvete, ele viu que tinha muitas outras crianças na rua. Mas ele não tinha dinheiro para o sorvete de todas as crianças. Então ele pegou o pouco dinheiro que tinha, deu para as quatro crianças daquela família e pediu que não contassem para as demais, pois ele não tinha dinheiro para comprar sorvetes para todos. E assim foi feito. Ele fez as quatro crianças muito, mas muito felizes mesmo. Num local onde assola a fome, tomar um sorvete é um luxo inimaginável.",
