      "Primeiro de maio. Dia do trabalhador. O Frei Rui sempre deu muita importância ao trabalho. Tanto que não parava de trabalhar. Além das suas atividades como religioso franciscano, o Frei Rui trabalhava em várias frentes: carregava caminhão, construía casas, fazia marcenaria, transporte, carregava móveis, saco de cimento, areia e tudo o que fosse necessário ao outro. Plantava, roçava, colhia, pescava e dava o fruto do seu trabalho para minimizar a fome e o sofrimento dos demais. Era excelente escritor, poeta, pensador, filósofo. Tinha o dom da oratória. Cantava muito bem e até tocava violão. O Frei trabalhava tanto que não cabe aqui detalhar, mas sim lembrar o quanto ele achava importante o trabalho. E é mesmo. O trabalho dignifica o ser humano. Congrega. Qualquer trabalho. Do simples ao mais complexo. Do pago ao voluntário. Hoje é o Dia do Trabalhador. Parabéns!",
